#!/usr/bin/env python3
"""Apply script: case status checklist + 7x faster Portfolio Insights.

Run from the HealthCross repo root: python3 apply_case_status_and_insights_speedup.py
"""
import base64, hashlib, os, sys

MARKER = "CASE_STATUS_AND_INSIGHTS_SPEEDUP_2026_08_04"

FILES = [
    {
        'path': 'app/api/routes_cases.py',
        'sha256': '0739224b5bd6a4c26dc10af20d3af7aefddd9a4bb343eaa67d11c8e4193f3d13',
        'size': 28776,
        'b64': '',
    },
    {
        'path': 'app/api/routes_portfolio_analysis.py',
        'sha256': '9d810c00cd9c52181744d252126015df5c5bdff665e239000cce1e8856bfc1df',
        'size': 22071,
        'b64': '',
    },
    {
        'path': 'app/models/schemas.py',
        'sha256': '58bf2be7489ab1871cbe30ae3204280d6fb45c315e21cee8dab6ca7411063025',
        'size': 13495,
        'b64': '',
    },
    {
        'path': 'app/static/index.html',
        'sha256': '7da23f3c54dca46547be644664ed151f3fea9d62d09e933a111a824bc14faefb',
        'size': 140386,
        'b64': '',
    },
    {
        'path': 'tests/test_api_portfolio_analysis.py',
        'sha256': '6ce8be3d87c13ef444caacb15ab9cc9797c630441c586e5c818ec67ca91c9f89',
        'size': 33347,
        'b64': '',
    },
    {
        'path': 'tests/test_api_case_completeness.py',
        'sha256': 'a9642c3c261f0151f3743632bdc44bb4ad3ee8966ae114b3dc72685745b4fdc7',
        'size': 3522,
        'b64': '',
    },
]


def main():
    repo_root = os.getcwd()
    ok = True
    for entry in FILES:
        path = os.path.join(repo_root, entry['path'])
        data = base64.b64decode(entry['b64'])
        if len(data) != entry['size']:
            print(f"SIZE MISMATCH before write: {entry['path']}")
            ok = False
            continue
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as f:
            f.write(data)
        with open(path, 'rb') as f:
            written = f.read()
        actual_sha = hashlib.sha256(written).hexdigest()
        if actual_sha == entry['sha256']:
            print(f"OK  {entry['path']}  ({len(written)} bytes, sha256={actual_sha[:12]}...)")
        else:
            print(f"CHECKSUM MISMATCH  {entry['path']}  expected={entry['sha256'][:12]}... actual={actual_sha[:12]}...")
            ok = False
    if ok:
        print(f"\nAll files written and verified. Marker: {MARKER}")
        print("Next: python3 -m pytest -q   (should show 453 passed)")
        print("Then: git add -A && git commit -m '...' && git push")
    else:
        print("\nSOME FILES FAILED TO VERIFY - do not commit. Re-run this script once more first.")
        sys.exit(1)


if __name__ == '__main__':
    main()
